import {readJson} from './data-loader-20261030-r1.js';
const base=new URL('../',import.meta.url);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Number(v).toLocaleString('zh-CN');
const $=id=>document.getElementById(id);
const cmp=(a,b)=>a===b?0:a<b?-1:1;
export const csvCell=v=>'"'+String(v??'').replace(/^[\s\u0000-\u001f]*[=+@-]/,m=>"'"+m).replace(/"/g,'""')+'"';
export function toCsv(rows,kind){const key=kind==='urls'?'url':'domain';return '\ufeff'+[['排名',kind==='urls'?'具体网址':'来源域名','页面标题','原始引用次数','覆盖回答数','覆盖问题数'],...rows.map((x,i)=>[i+1,x[key],x.title||'',x.rawCitationCount,x.coverageAnswers,x.coverageQuestions])].map(r=>r.map(csvCell).join(',')).join('\r\n')+'\r\n';}
export function layout({current,group,count,tabs,summary,section,downloads}){
 const totals=(group==='all'?current.totals:current.groups[group]),c=totals.citations;
 const kpi=(label,value,note)=>`<div><dt>${esc(label)}</dt><dd>${n(value)}</dd><small>${esc(note)}</small></div>`;
 const core=`${tabs}${summary}<dl class="r3-kpis">${kpi('原始来源卡',c.rawCitationCount+c.noUrlSourceCards,'含带网址卡与空来源卡')}${kpi('原始带网址来源卡',c.rawCitationCount,'同一网址重复出现照计')}${kpi('无网址空来源卡',c.noUrlSourceCards,'独列，不并入网址与域名集合')}${kpi('完整唯一网址',c.globallyUniqueUrlCount,'沿用保存的规范化键 · 主分析V1')}${kpi('完整来源域名',c.domainCount,'按网址hostname聚合')}${kpi('回答内去重引用事件',c.normalizedCitationCount,'同一回答内同一规范化网址仅计一次')}</dl><div class="conclusion"><div class="conclusion-label">当前范围</div><p class="conclusion-text">${group==='all'?'总数据':esc(group)+'组'} · ${count}道问题 · ${n(totals.validAnswers)}份有效回答。引用次数、覆盖回答和覆盖问题分别统计；点击来源可回看全部命中回答与具体卡片。</p></div>`;
 const boundaries='<p>网址沿用原答保存的 normalizedUrl，不重新裁定归一化。原始引用次数按每张带网址来源卡计数；覆盖回答、覆盖问题按各自集合去重。域名按 hostname 聚合，不将空来源卡归入任何域名。</p><p>第三轮全轮主分析V1唯一网址为3,494；历史字段3,498及尾斜杠差4继续保留。原始卡13,313张，其中带网址10,336张、空卡2,977张。上方实时指标与聚合表随所选分组变化，以上历史说明仅指全轮。</p><p>只描述保存回答中的引用，不推断算法权重、选择概率或浏览点击。跨日期与采集方式变化不直接归因于GEO优化；未知、不适用与已观察到零分别保留。</p>';
 const content=section('overview','核心结论',core)+section('sources','全部网址与域名','<p>完整集合按原始引用次数降序，同次数按网址或域名的固定字符顺序排列。</p><div id="citation-aggregate"></div>')+section('citation-detail','逐张来源卡完整清单','<p>保留原有逐张来源卡，包括空来源卡；展开后独立读取原答分片。</p><div id="citation-list"></div>')+section('specialists','抖音、社媒、商品链接与产品事实','<div id="specialist-content"></div>')+section('answers','逐问题与完整原回答','<div id="answer-list"></div>')+'<section id="answer-detail" class="r3-answer" tabindex="-1" hidden></section>'+section('quality','数据边界与可复核性',boundaries)+section('downloads','数据与完整明细下载',downloads);
 return `<div class="layout"><nav class="side-nav" aria-label="报告目录">${[['overview','核心结论'],['sources','全部网址与域名'],['citation-detail','逐张完整清单'],['specialists','专项与产品事实'],['answers','问题与原回答'],['quality','数据边界'],['downloads','数据下载']].map(([id,t])=>`<a href="#${id}">${t}</a>`).join('')}</nav><div class="report-body">${content}</div></div>`;
}
export async function mount(group){
 const data=await readJson(new URL(`assets/citation-restoration-20261101/${group}.json`,base));
 if(data.group!==group||data.version!=='MAKA-CITATION-RESTORATION-V1-20261101')throw Error('引用聚合版本不匹配');
 const host=$('citation-aggregate');let page=1,current=[],kind='urls';
 host.innerHTML=`<p id="source-scope">${group==='all'?'总数据':esc(group)+'组'} · ${n(data.totals.validAnswers)}份回答 · ${n(data.totals.questions)}道问题</p><div class="source-controls"><label>搜索网址、域名或标题<input id="source-search" type="search" placeholder="输入关键词"></label><label>清单类型<select id="source-kind"><option value="urls">全部网址</option><option value="domains">全部域名</option></select></label><label>每页条数<select id="source-size"><option>25</option><option selected>50</option><option>100</option><option value="all">全部</option></select></label><button class="r3-button" id="source-reset" type="button">重置</button></div><p id="source-count" aria-live="polite"></p><div class="source-actions"><button class="r3-button" id="export-all" type="button">导出本组全部网址</button><button class="r3-button" id="export-filtered" type="button">导出当前筛选网址</button></div><div id="source-results"></div><div class="r3-pager"><button type="button" id="source-prev">上一页</button><span id="source-page"></span><button type="button" id="source-next">下一页</button></div><section id="source-trace" tabindex="-1" hidden></section>`;
 const hideTrace=()=>{$('source-trace').hidden=true;};
 function render(){kind=$('source-kind').value;const q=$('source-search').value.trim().toLowerCase(),all=data[kind];current=all.filter(x=>[x.url,x.domain,x.title].join(' ').toLowerCase().includes(q));const size=$('source-size').value==='all'?Math.max(1,current.length):Number($('source-size').value),pages=Math.max(1,Math.ceil(current.length/size));page=Math.max(1,Math.min(page,pages));const start=(page-1)*size,rows=current.slice(start,start+size),name=kind==='urls'?'网址':'域名';
  $('source-count').textContent=`${n(current.length)} / ${n(all.length)} 个${name} · ${current.length?start+1:0}–${Math.min(start+size,current.length)} · 原始引用次数降序`;
  $('export-all').textContent=`导出本组全部${name}`;$('export-filtered').textContent=`导出当前筛选${name}`;
  $('source-results').innerHTML=`<div class="table-wrap" tabindex="0" role="region" aria-label="完整来源聚合表"><table><thead><tr><th>排名</th><th>${kind==='urls'?'具体网址 / 页面标题':'来源域名'}</th><th>原始引用次数</th><th>覆盖回答数</th><th>覆盖问题数</th><th>命中明细</th></tr></thead><tbody>${rows.length?rows.map((x,i)=>`<tr><td class="source-rank numeric">${start+i+1}</td><td class="source-label">${kind==='urls'?`<a href="${esc(x.url)}" rel="noopener noreferrer" target="_blank">${esc(x.title)}</a><small class="source-url">${esc(x.url)}</small>`:esc(x.domain)}</td><td class="numeric">${n(x.rawCitationCount)}</td><td class="numeric">${n(x.coverageAnswers)}</td><td class="numeric">${n(x.coverageQuestions)}</td><td><button type="button" class="r3-button source-open" data-index="${start+i}">查看命中问题</button></td></tr>`).join(''):'<tr><td colspan="6">没有符合当前筛选的来源。清空关键词或重置筛选后重试。</td></tr>'}</tbody></table></div>`;
  $('source-page').textContent=`第 ${page} / ${pages} 页`;$('source-prev').disabled=page===1;$('source-next').disabled=page===pages;
 }
 for(const id of ['source-search','source-kind','source-size'])$(id).addEventListener(id==='source-search'?'input':'change',()=>{page=1;hideTrace();render();});
 $('source-reset').onclick=()=>{$('source-search').value='';$('source-kind').value='urls';$('source-size').value='50';page=1;hideTrace();render();};
 $('source-prev').onclick=()=>{page--;render();};$('source-next').onclick=()=>{page++;render();};
 function download(rows,scope){const blob=new Blob([toCsv(rows,kind)],{type:'text/csv;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`玛卡星球-第三轮-${group==='all'?'总数据':group+'组'}-${kind==='urls'?'网址':'域名'}-${scope}.csv`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),30000);}
 $('export-all').onclick=()=>download(data[kind],'全量');$('export-filtered').onclick=()=>download(current,'当前筛选');
 $('source-results').onclick=ev=>{const b=ev.target.closest('.source-open');if(b)trace(current[Number(b.dataset.index)]);};
 function trace(item){const related=kind==='urls'?[item]:data.urls.filter(x=>x.domain===item.domain),refs=new Map();for(const u of related)for(const [sid,positions]of u.refs){if(!refs.has(sid))refs.set(sid,new Set());positions.forEach(p=>refs.get(sid).add(p));}
  const records=[...refs].map(([sid,positions])=>({sid,...data.samples[sid],positions:[...positions].sort((a,b)=>a-b)})).sort((a,b)=>cmp(a.questionId,b.questionId)||cmp(a.businessDate,b.businessDate)||a.repeat-b.repeat||cmp(a.sid,b.sid));
  const questions=[...new Map(records.map(x=>[x.questionId,x.questionText]))].sort((a,b)=>cmp(a[0],b[0]));let tracePage=1;const target=$('source-trace');target.hidden=false;
  target.innerHTML=`<h3>命中问题与全部相关原答</h3><p style="overflow-wrap:anywhere">${esc(item.url||item.domain)}</p><p id="source-trace-count">${n(questions.length)}道问题 · ${n(records.length)}份原答 · ${n(item.rawCitationCount)}张带网址卡</p><div class="source-controls"><label>命中问题<select id="trace-question"><option value="">全部命中问题</option>${questions.map(([id,t])=>`<option value="${esc(id)}">${esc(t)}</option>`).join('')}</select></label></div><div id="trace-rows"></div><div class="r3-pager"><button type="button" id="trace-prev">上一页</button><span id="trace-page"></span><button type="button" id="trace-next">下一页</button></div>`;
  const draw=()=>{const chosen=$('trace-question').value,rows=records.filter(x=>!chosen||x.questionId===chosen),pages=Math.max(1,Math.ceil(rows.length/25));tracePage=Math.max(1,Math.min(tracePage,pages));$('trace-rows').innerHTML=`<div class="table-wrap" tabindex="0" role="region" aria-label="全部命中原答"><table><thead><tr><th>命中问题</th><th>日期 / 回答次序</th><th>全部对应来源卡</th></tr></thead><tbody>${rows.slice((tracePage-1)*25,tracePage*25).map(x=>`<tr><th scope="row">${esc(x.questionText)}</th><td>${esc(x.businessDate)}<br>第${x.repeat}次回答</td><td>${x.positions.map(p=>{const u=new URL('round3/data/',base);if(group!=='all')u.searchParams.set('group',group);u.searchParams.set('sample',x.sid);u.searchParams.set('card',p);u.hash='answer-card-'+p;return `<a class="source-card-link" href="${esc(u.href)}">查看原答 · 来源卡 ${p+1}</a>`;}).join('<br>')}</td></tr>`).join('')}</tbody></table></div>`;$('trace-page').textContent=`第 ${tracePage} / ${pages} 页 · ${n(rows.length)}份原答`;$('trace-prev').disabled=tracePage===1;$('trace-next').disabled=tracePage===pages;};
  $('trace-question').onchange=()=>{tracePage=1;draw();};$('trace-prev').onclick=()=>{tracePage--;draw();};$('trace-next').onclick=()=>{tracePage++;draw();};draw();target.scrollIntoView({block:'start'});target.focus({preventScroll:true});
 }
 $('print-report').onclick=()=>window.print();render();
}
